\begin{theorem}
  \label{thm:Artin-Schreier_weak}
  \uses{def:RCF}
  \lean{weak_Artin_Schreier}
  \leanok
  Let $R$ be a field with $\ch K\neq2$, and suppose $[\bar{R}:R]=2$. Then $R$ is real closed.
\end{theorem}

n30008.content:
\begin{proof}
  \uses{lem:FTAlg_converse_alg_closure}
  By Lemma \ref{lem:FTAlg_converse_alg_closure}, it suffices to show that $\bar{R}\cong R(i)$.

  Since $\ch\bar{R}\neq 2$, we have $\bar{R}\cong R(\sqrt{a})$ for some non-square $a\in R$. Since $R(\sqrt{a})$ is algebraically closed, $\sqrt{a}$ is a square in $R(\sqrt{a})$; find $x,y\in R$ such that $\sqrt{a}=(x+y\sqrt{a})^2$. Expanding and comparing coefficients, $x^2+y^2a=0$ and $2xy=1$. Rearranging, $a=-(4x^4)=-1\cdot(2x^2)^2$. Rescaling by $2x^2$, $R(i)\cong R(\sqrt{a})=\bar{R}$.
\end{proof}

